using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using Microsoft.EntityFrameworkCore;using AutoPecasERP.Services.Seguranca;
namespace AutoPecasERP.Desktop.Views;
public partial class ConfiguracaoFiscalWindow:Window{readonly ErpDbContext _db=new();ConfiguracaoFiscal? _cfg;public ConfiguracaoFiscalWindow(){InitializeComponent();Ambiente.ItemsSource=new[]{"HOMOLOGACAO","PRODUCAO"};Loaded+=Carregar;}
async void Carregar(object s,RoutedEventArgs e){_cfg=await _db.ConfiguracoesFiscais.FirstOrDefaultAsync()??new();Razao.Text=_cfg.RazaoSocial;Fantasia.Text=_cfg.NomeFantasia;Cnpj.Text=_cfg.Cnpj;Ie.Text=_cfg.InscricaoEstadual;Uf.Text=_cfg.Uf;Ibge.Text=_cfg.CodigoMunicipioIbge;Ambiente.SelectedItem=_cfg.Ambiente;Certificado.Text=_cfg.CaminhoCertificadoA1;SerieNfe.Text=_cfg.SerieNFe.ToString();SerieNfce.Text=_cfg.SerieNFCe.ToString();}
async void Salvar_Click(object s,RoutedEventArgs e){if(_cfg==null)return;_cfg.RazaoSocial=Razao.Text;_cfg.NomeFantasia=Fantasia.Text;_cfg.Cnpj=Cnpj.Text;_cfg.InscricaoEstadual=Ie.Text;_cfg.Uf=Uf.Text.ToUpper();_cfg.CodigoMunicipioIbge=Ibge.Text;_cfg.Ambiente=Ambiente.SelectedItem?.ToString()??"HOMOLOGACAO";_cfg.CaminhoCertificadoA1=Certificado.Text;if(!string.IsNullOrWhiteSpace(Senha.Password))_cfg.SenhaCertificadoProtegida=SecretProtector.Protect(Senha.Password);int.TryParse(SerieNfe.Text,out var a);int.TryParse(SerieNfce.Text,out var b);_cfg.SerieNFe=a==0?1:a;_cfg.SerieNFCe=b==0?1:b;if(_cfg.Id==0)_db.ConfiguracoesFiscais.Add(_cfg);await _db.SaveChangesAsync();MessageBox.Show("Configuração fiscal salva. A senha do certificado foi protegida para o usuário atual do Windows.");Close();}}